<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f6f7f2"><title>LinkGo | Admin Desa</title>
<style>
:root{font-family:Arial,sans-serif;color:#202b24;background:#f6f7f2;--green:#244f40;--line:#d4dfd0;--muted:#66736a}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}header{background:#163d32;color:#f6f8ef;padding:18px 0}.shell{width:min(1120px,calc(100% - 36px));margin:auto}.bar{display:flex;justify-content:space-between;align-items:center;gap:12px}.brand{font-weight:800}.brand small{display:block;font-weight:400;color:#dce7dd;margin-top:3px}a{color:inherit}main{padding:32px 0 70px}h1{font:400 clamp(36px,5vw,54px)/1 Georgia,serif;letter-spacing:-.04em;margin:0}h2{font-size:21px;margin:0 0 4px}.muted,.hint{color:var(--muted)}.muted{margin:8px 0 20px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;margin:15px 0}.login{max-width:430px;margin:35px auto}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field{display:grid;gap:5px}.field.wide{grid-column:1/-1}.field label{font-size:13px;font-weight:700}.field input,.field textarea,.field select{width:100%;border:1px solid #afbdad;border-radius:8px;padding:10px 11px;background:white;color:#202b24}.field textarea{min-height:74px;resize:vertical}.check{display:flex;gap:8px;align-items:center;font-size:13px;color:var(--muted)}.btn{border:0;border-radius:8px;background:var(--green);color:white;font-weight:700;padding:10px 14px;cursor:pointer}.btn:hover{background:#163d32}.btn.light{background:#e8efe4;color:#244f40}.btn.red{background:#f5e7e4;color:#823b32}.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:13px}.notice{font-size:13px;min-height:20px;color:var(--muted)}.notice.error{color:#a3342a}.notice.ok{color:#2f6138}.list{display:grid;gap:9px;margin-top:15px}.item{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 13px;border:1px solid #e0e7dd;border-radius:9px;background:#fbfcfa}.item strong{display:block}.item small{display:block;color:var(--muted);margin-top:4px}.actions{display:flex;gap:6px;flex-wrap:wrap}.actions button{padding:7px 10px;font-size:12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #e4e9e1}th{color:#526158;font-size:12px}.status{display:inline-block;border-radius:20px;padding:4px 8px;background:#eaf0e5;font-size:11px;font-weight:700;white-space:nowrap}.empty{padding:18px;border:1px dashed #bfcdb9;border-radius:9px;color:var(--muted);font-size:13px}.section-top{display:flex;justify-content:space-between;align-items:start;gap:12px}.optional{font-size:12px;color:var(--muted);font-weight:400}.danger{color:#923a32}@media(max-width:650px){.grid{grid-template-columns:1fr}.bar{align-items:flex-start}.item{align-items:flex-start;flex-direction:column}main{padding-top:24px}}
</style><style>#otp-field[hidden],#project-form[hidden],#budget-form[hidden]{display:none!important}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:15px 0}.metric{background:#eaf0e5;border:1px solid #d5e1d0;border-radius:11px;padding:14px}.metric strong{display:block;font-size:25px;color:#244f40}.metric span{font-size:12px;color:#66736a}@media(max-width:650px){.stats{grid-template-columns:1fr}}</style><style>.content-managers{display:grid;gap:20px}.content-manager{padding-top:18px;border-top:1px solid var(--line)}.content-manager:first-child{padding-top:0;border-top:0}.content-manager h3{margin:0;font-size:17px}.content-manager .muted{margin:5px 0 10px;font-size:14px}.content-form{padding:16px;margin-top:12px;border:1px solid var(--line);border-radius:10px;background:#fbfcfa}.content-form[hidden]{display:none!important}@media(min-width:900px){.content-form{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.content-manager>.section-top{align-items:flex-start}.content-form{padding:12px}}</style><style>
body.auth-page{min-height:100vh;background:radial-gradient(ellipse at 50% 88%,#e7eee4 0,transparent 48%),#f4f6f2}
.auth-page header{padding:17px 0;background:#fff;color:#203a2f;border-bottom:1px solid #e0e7dd}
.auth-page .bar{justify-content:flex-start}
.auth-page .brand{display:flex;align-items:center;gap:11px;font-size:15px;letter-spacing:.01em}
.auth-page .brand::before{content:"";width:42px;height:42px;flex:0 0 42px;border-radius:11px;background:#f4f9fc url('/images/portal-logo.webp') center/cover no-repeat;border:1px solid #d8e4e9}
.auth-page .brand small{color:#68766e;font-size:12px;letter-spacing:0}
.auth-page main.shell{display:grid;min-height:calc(100vh - 77px);place-items:center;padding:42px 18px}
.auth-page .login{width:min(100%,460px);max-width:460px;margin:0;padding:clamp(28px,5vw,42px);border:1px solid #dce5d9;border-radius:18px;box-shadow:0 22px 60px rgb(25 55 39 / 9%)}
.auth-page .login .hint{margin:0 0 12px;color:#64776a;font-size:11px;font-weight:700;letter-spacing:.14em}
.auth-page .login h1{font:600 36px/1.1 Arial,sans-serif;letter-spacing:-.045em;color:#1c3429}
.auth-page .login form{gap:17px;margin-top:27px}
.auth-page .login .field{gap:7px}
.auth-page .login .field label{font-size:13px;color:#33443a}
.auth-page .login .field input{min-height:49px;padding:12px 13px;border-color:#c8d3c6;border-radius:9px;transition:border-color .16s ease,box-shadow .16s ease}
.auth-page .login .field input:focus{outline:0;border-color:#52745b;box-shadow:0 0 0 3px rgb(82 116 91 / 15%)}
.auth-page .login .btn{grid-column:1/-1;width:100%;min-height:48px;margin-top:2px;border-radius:9px;background:#244f40}
.auth-page .login .btn:hover{background:#173d31}
.auth-page .login .notice{margin:10px 0 0}
@media(max-width:600px){.auth-page header{padding:13px 0}.auth-page .brand::before{width:38px;height:38px;flex-basis:38px}.auth-page main.shell{min-height:calc(100svh - 65px);padding:24px 16px}.auth-page .login{padding:27px 22px;border-radius:15px}.auth-page .login h1{font-size:32px}}
</style>
<style>
body.dashboard-page{min-height:100vh;background:#f4f6f3}
.dashboard-page header{position:sticky;top:0;z-index:40;padding:0;background:#fff;color:#203a2f;border-bottom:1px solid #e0e7dd;box-shadow:0 2px 12px rgb(25 55 39 / 4%)}
.dashboard-page header .bar{width:100%;min-height:68px;padding:0 26px;justify-content:flex-start}
.dashboard-page .brand{font-size:15px;letter-spacing:.01em}
.dashboard-page .brand small{color:#68766e;font-size:12px;letter-spacing:0}
.dashboard-topbar-spacer{flex:1}
.auth-page .dashboard-topbar-spacer{display:none}
.dashboard-page #logout{white-space:nowrap}
.dashboard-page main.shell{width:100%;max-width:none;padding:0}
#dashboard[hidden]{display:none!important}
#dashboard .admin-page[hidden]{display:none!important}
#dashboard.dashboard-layout{display:grid;grid-template-columns:252px minmax(0,1fr);min-height:calc(100vh - 68px)}
.admin-sidebar{position:sticky;top:68px;align-self:start;height:calc(100vh - 68px);overflow-y:auto;padding:23px 14px;background:#fff;border-right:1px solid #e0e7dd}
.admin-sidebar-heading{margin:0 12px 12px;color:#7b887f;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.admin-nav{display:grid;gap:4px}
.admin-nav a{display:flex;min-height:44px;align-items:center;gap:12px;padding:10px 12px;border-radius:9px;color:#536158;text-decoration:none;font-size:14px;font-weight:600;transition:background .16s ease,color .16s ease}
.admin-nav a:hover,.admin-nav a[aria-current="page"]{background:#eaf1e9;color:#244f40}
.admin-nav a[hidden]{display:none!important}
.admin-nav svg{width:19px;height:19px;flex:0 0 19px;stroke:currentColor;stroke-width:1.8;fill:none;stroke-linecap:round;stroke-linejoin:round}
.admin-nav-divider{height:1px;margin:12px 8px;background:#e6ebe4}
.admin-sidebar-note{margin:24px 8px 0;padding:13px;border-radius:10px;background:#f5f7f3;color:#647168;font-size:12px;line-height:1.5}
.admin-sidebar-note strong{display:block;margin-bottom:3px;color:#2c4638;font-size:13px}
.admin-content{width:min(1320px,100%);min-width:0;margin:0 auto;padding:30px clamp(20px,3vw,44px) 64px}
.dashboard-page-heading{padding:0 2px}
.dashboard-page-heading h1{font:700 clamp(27px,3vw,34px)/1.15 Arial,sans-serif;letter-spacing:-.035em;color:#203a2f}
.dashboard-page-heading .hint{margin:0 0 7px;font-size:11px;font-weight:700;letter-spacing:.12em}
.dashboard-page-heading .muted{margin:7px 0 0}
.admin-content .section-top>.btn{white-space:nowrap}
.admin-content .card{margin:18px 0;border-radius:13px;box-shadow:0 2px 10px rgb(24 51 37 / 3%)}
.project-item{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:20px;padding:16px 18px}
.project-main{display:grid;min-width:0;gap:7px}
.project-title-row{display:flex;min-width:0;align-items:center;gap:9px;flex-wrap:wrap}
.project-title{margin:0;color:#24372c;font-size:17px;line-height:1.35}
.project-location{display:flex;align-items:center;gap:7px;margin:0;color:#35483b;font-size:15px;font-weight:600;line-height:1.4}
.project-location svg{width:17px;height:17px;flex:0 0 17px;stroke:#5a765f;stroke-width:1.8;fill:none;stroke-linecap:round;stroke-linejoin:round}
.project-meta{display:flex;align-items:center;gap:7px 13px;flex-wrap:wrap;color:#68766e;font-size:13px;line-height:1.4}
.project-budget{color:#315b43;font-size:14px;font-weight:700}
.project-card-actions{align-items:center}
.project-card-actions .delete-secondary{border:1px solid #eadbd8;background:#fff;color:#815149}
.project-card-actions .delete-secondary:hover{background:#fbf3f1;border-color:#d8bdb7}
#user-management.admin-page:not([hidden]){display:grid;gap:0}
#user-management .account-panel{margin:18px 0}
.account-panel .section-top{margin-bottom:14px}
.account-panel .section-top h2{font-size:18px}
.account-panel .section-top .muted{margin:5px 0 0}
.admin-user{display:grid;grid-template-columns:minmax(180px,1.2fr) repeat(2,minmax(145px,.8fr)) auto;gap:14px;align-items:end;padding:16px 0;border-bottom:1px solid #e5ebe3}
.admin-user:last-child{border-bottom:0}
.admin-user-identity{align-self:center;min-width:0}
.admin-user-identity strong{display:block;color:#26392d;font-size:15px}
.admin-user-identity small{display:block;margin-top:5px;color:#68766e;font-size:13px;overflow-wrap:anywhere}
.admin-user .field-label,.admin-user .field label{font-size:13px;font-weight:700;color:#33443a}
.account-value{display:flex;min-height:40px;align-items:center;padding:9px 11px;border:1px solid #e0e7dd;border-radius:8px;background:#f7f9f5;color:#536158}
.admin-user-self{background:#fff}
.admin-user-password{grid-column:1/-1;padding:10px 12px;border-radius:9px;background:#f6f8f4}
.admin-user-password summary{color:#315b43;font-size:14px;font-weight:700;cursor:pointer}
.admin-user-password .grid{margin-top:13px}
.admin-user-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.admin-user-actions .notice{min-height:0;margin:0}
.account-self-note{color:#68766e;font-size:13px}
.account-empty{margin-top:10px}
.content-manager .list .item{align-items:center}
.admin-content .stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:22px 0}
#analytics-management .stats{grid-template-columns:repeat(2,minmax(0,1fr))}
.admin-content .metric{min-height:90px;padding:17px 18px}
.admin-content .metric strong{font-size:27px}
.overview-shortcuts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:15px}
.overview-shortcuts a,.overview-request{display:flex;min-width:0;align-items:center;gap:12px;padding:15px;border:1px solid #e2e9e0;border-radius:10px;background:#fbfcfa;text-decoration:none;transition:border-color .16s ease,background .16s ease}
.overview-shortcuts a:hover,.overview-request:hover{border-color:#b9cbb8;background:#f5f8f3}
.shortcut-icon{display:grid;width:38px;height:38px;flex:0 0 38px;place-items:center;border-radius:10px;background:#eaf1e9;color:#244f40;font-size:12px;font-weight:800}
.overview-shortcuts a>span:nth-child(2),.overview-request>span:first-child{display:grid;min-width:0;gap:4px}
.overview-shortcuts strong,.overview-request strong{color:#273c30;font-size:14px}
.overview-shortcuts small,.overview-request small{color:#68766e;font-size:12px;line-height:1.4}
.shortcut-arrow{margin-left:auto;color:#55725e;font-size:21px}
.overview-request{justify-content:space-between}
.text-link{color:#315b43;font-size:13px;font-weight:700;text-decoration:none}
.text-link:hover{text-decoration:underline}
#sidebar-toggle{display:none;width:40px;height:40px;place-items:center;border:1px solid #dce5dc;border-radius:9px;background:#fff;color:#244f40;cursor:pointer}
#sidebar-toggle svg{width:20px;height:20px;stroke:currentColor;stroke-width:2;fill:none;stroke-linecap:round}
#sidebar-backdrop[hidden]{display:none!important}
@media(max-width:900px){
  #dashboard.dashboard-layout{display:block}
  .dashboard-page header .bar{min-height:62px;padding:0 16px;gap:12px}
  #sidebar-toggle{display:grid;flex:0 0 40px}
  #sidebar-toggle[hidden]{display:none!important}
  .admin-sidebar{position:fixed;z-index:51;top:62px;bottom:0;left:0;width:min(300px,86vw);overflow-y:auto;transform:translateX(-102%);transition:transform .2s ease;box-shadow:12px 0 30px rgb(20 45 32 / 10%)}
  .admin-sidebar.is-open{transform:translateX(0)}
  #sidebar-backdrop:not([hidden]){position:fixed;z-index:50;inset:62px 0 0;width:100%;border:0;background:rgb(17 34 25 / 38%)}
  .admin-content{padding:23px 18px 48px}
}
@media(max-width:650px){.project-item{grid-template-columns:1fr;gap:12px;padding:14px}.project-title{font-size:16px}.project-location{font-size:14px}.project-card-actions{justify-content:flex-start}.admin-user{grid-template-columns:1fr 1fr;align-items:start}.admin-user-identity,.admin-user-password,.admin-user-actions{grid-column:1/-1}.admin-user .field{align-content:start}.admin-user-actions{justify-content:space-between}}
@media(max-width:600px){
  .admin-content .stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .admin-content .metric{min-height:78px;padding:12px 10px}
  .admin-content .metric strong{font-size:21px}
  .admin-content .metric span{font-size:11px;line-height:1.35}
  .overview-shortcuts{grid-template-columns:1fr}
  .overview-request{align-items:flex-start}
}
@media(prefers-reduced-motion:reduce){.admin-nav a,.overview-shortcuts a,.overview-request,#sidebar-toggle,.admin-sidebar{transition:none}}
</style></head><body class="{{ $isAdminAuthenticated ? 'dashboard-page' : 'auth-page' }}" data-admin-page="{{ $adminPage }}">
<header><div class="shell bar"><button id="sidebar-toggle" type="button" aria-label="Buka navigasi" aria-expanded="false" aria-controls="admin-sidebar" @if (! $isAdminAuthenticated) hidden @endif><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button><div class="brand">LinkGo <small id="admin-village-name">{{ $adminVillageName }}</small></div><div class="dashboard-topbar-spacer"></div><button id="logout" class="btn light" type="button" @if (! $isAdminAuthenticated) hidden @endif>Keluar</button></div></header>
<main class="shell">
<section id="login" class="card login" @if ($isAdminAuthenticated) hidden @endif><p class="hint">LINKGO · ADMINISTRASI</p><h1>Masuk</h1><form id="login-form" class="grid"><div class="field wide"><label for="username">Nama pengguna</label><input id="username" autocomplete="username" required></div><div class="field wide"><label for="password">Kata sandi</label><input id="password" type="password" autocomplete="current-password" required></div><button class="btn wide" type="submit">Masuk</button></form><p id="login-note" class="notice" role="status"></p></section>
<section id="dashboard" class="dashboard-layout" @if (! $isAdminAuthenticated) hidden @endif>
<aside id="admin-sidebar" class="admin-sidebar" aria-label="Navigasi dashboard">
    <p class="admin-sidebar-heading">Menu utama</p>
    <nav class="admin-nav" aria-label="Menu admin">
        <a href="/admin/dashboard" data-admin-link="dashboard" @if ($adminPage === 'dashboard') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="5" rx="1.5"/><rect x="13" y="10" width="8" height="11" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/></svg><span>Ringkasan</span></a>
        <a href="/admin/projects" data-admin-link="projects" @if ($adminPage === 'projects') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 4h8l4 4v12H4V4h4Z"/><path d="M8 4v5h8V4M8 14h8M8 17h5"/></svg><span>Papan proyek</span></a>
        <a href="/admin/budgets" data-admin-link="budgets" @if ($adminPage === 'budgets') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 19V5M4 19h16"/><path d="m7 15 4-4 3 2 5-6"/><path d="M16 7h3v3"/></svg><span>APBDes</span></a>
        <a href="/admin/proposals" data-admin-link="proposals" @if ($adminPage === 'proposals') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 3.5 7.5 12 12l8.5-4.5L12 3Z"/><path d="m5.5 9.5 6.5 3.5 6.5-3.5M5.5 13 12 16.5l6.5-3.5M5.5 16.5 12 20l6.5-3.5"/></svg><span>Usulan warga</span></a>
        <a href="/admin/requests" data-admin-link="requests" @if ($adminPage === 'requests') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v14H4z"/><path d="m4 7 8 6 8-6M8 17h8"/></svg><span>Permintaan warga</span></a>
        <div class="admin-nav-divider" role="separator"></div>
        <a href="/admin/content" data-admin-link="content" @if ($adminPage === 'content') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h9l4 4v14H6z"/><path d="M15 3v5h5M9 12h7M9 16h7"/></svg><span>Konten website</span></a>
        <a href="/admin/media" data-admin-link="media" @if ($adminPage === 'media') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9" r="1.5"/><path d="m4 17 5-5 4 4 3-3 4 4"/></svg><span>Media desa</span></a>
        <a href="/admin/analytics" data-admin-link="analytics" @if ($adminPage === 'analytics') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20V10h4v10M10 20V4h4v16M16 20v-7h4v7"/></svg><span>Analitik</span></a>
        <a id="nav-users" href="/admin/users" data-admin-link="users" @if (! $canManageUsers || ! $isAdminAuthenticated) hidden @endif @if ($adminPage === 'users') aria-current="page" @endif><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="3"/><path d="M3.5 20a5.5 5.5 0 0 1 11 0M16 5.5a3 3 0 0 1 0 5.8M17 14a5 5 0 0 1 3.5 4.8"/></svg><span>Akun admin</span></a>
    </nav>
    <div class="admin-sidebar-note"><strong>Ruang kerja desa</strong>Data yang dikelola di sini hanya tampil pada website desa ini.</div>
</aside>
<button id="sidebar-backdrop" type="button" aria-label="Tutup navigasi" hidden></button>
<div class="admin-content">
<div class="dashboard-page-heading"><div><p class="hint">RUANG ADMIN DESA</p><h1 id="dashboard-page-title">{{ ['dashboard' => 'Dashboard', 'projects' => 'Papan proyek', 'budgets' => 'APBDes', 'proposals' => 'Usulan warga', 'requests' => 'Permintaan warga', 'content' => 'Konten website', 'media' => 'Media desa', 'analytics' => 'Analitik', 'users' => 'Akun admin'][$adminPage] }}</h1><p id="dashboard-page-description" class="muted">{{ ['dashboard' => 'Ringkasan pengelolaan website desa.', 'projects' => 'Kelola informasi pekerjaan dan pembangunan desa.', 'budgets' => 'Kelola ringkasan anggaran desa per tahun.', 'proposals' => 'Tinjau dan tindak lanjuti usulan pembangunan.', 'requests' => 'Kelola layanan dan pengaduan yang dikirim warga.', 'content' => 'Kelola berita, layanan, serta profil dan potensi desa.', 'media' => 'Kelola gambar yang digunakan pada website desa.', 'analytics' => 'Pantau jumlah tampilan halaman website desa.', 'users' => 'Kelola akun yang memiliki akses ke dashboard desa.'][$adminPage] }}</p><p id="dashboard-load-note" class="notice" role="status" hidden></p></div></div>
<section id="dashboard-overview" class="admin-page" data-admin-page="dashboard" @if ($adminPage !== 'dashboard') hidden @endif>
<div class="stats"><div class="metric"><strong id="project-total">0</strong><span>Proyek ditayangkan</span></div><div class="metric"><strong id="budget-total">0</strong><span>Data APBDes</span></div><div class="metric"><strong id="proposal-total">0</strong><span>Usulan masuk</span></div><div class="metric"><strong id="request-total">0</strong><span>Permintaan masuk</span></div></div>
<section class="card overview-card"><div class="section-top"><div><h2>Akses cepat</h2><p class="muted">Langsung buka bagian yang ingin dikelola.</p></div></div><div class="overview-shortcuts"><a href="/admin/projects"><span class="shortcut-icon">01</span><span><strong>Papan proyek</strong><small>Tambah dan perbarui proyek desa</small></span><span class="shortcut-arrow" aria-hidden="true">→</span></a><a href="/admin/budgets"><span class="shortcut-icon">02</span><span><strong>APBDes</strong><small>Kelola ringkasan anggaran tahunan</small></span><span class="shortcut-arrow" aria-hidden="true">→</span></a><a href="/admin/requests"><span class="shortcut-icon">03</span><span><strong>Permintaan warga</strong><small>Tinjau layanan dan pengaduan</small></span><span class="shortcut-arrow" aria-hidden="true">→</span></a><a href="/admin/content"><span class="shortcut-icon">04</span><span><strong>Konten website</strong><small>Perbarui berita, layanan, dan profil</small></span><span class="shortcut-arrow" aria-hidden="true">→</span></a></div></section>
<section class="card overview-card"><div class="section-top"><div><h2>Permintaan terbaru</h2><p class="muted">Permintaan warga yang paling baru diterima.</p></div><a class="text-link" href="/admin/requests">Lihat semua</a></div><div id="overview-requests" class="list"><div class="empty">Belum ada permintaan warga.</div></div></section>
</section>
<section class="card admin-page admin-section" id="project-management" data-admin-page="projects" @if ($adminPage !== 'projects') hidden @endif><div class="section-top"><div><h2>Papan proyek</h2><p class="muted">Daftar proyek dan status publikasinya.</p></div><button id="project-add" class="btn" type="button">Tambah proyek</button></div><form hidden id="project-form" class="grid"><input type="hidden" name="id"><div class="field"><label>Nama proyek</label><input name="title" required></div><div class="field"><label>Lokasi</label><input name="location" required></div><div class="field"><label>Latitude <span class="optional">(opsional)</span></label><input name="latitude" type="number" min="-90" max="90" step="any" placeholder="Contoh: -7.754321"></div><div class="field"><label>Longitude <span class="optional">(opsional)</span></label><input name="longitude" type="number" min="-180" max="180" step="any" placeholder="Contoh: 113.215678"></div><div class="field"><label>Tahun</label><input name="year" type="number" min="2000" max="2100" required></div><div class="field"><label>Status pekerjaan</label><select name="status"><option>Pekerjaan diberitakan</option><option>Dalam pengerjaan</option><option>Selesai</option><option>Usulan dibahas</option></select></div><div class="field"><label>Anggaran (rupiah)</label><input name="summary" placeholder="Contoh: Rp25.000.000"></div><div class="field"><label>Volume</label><input name="volume"></div><div class="field"><label>Sumber dana</label><input name="funding"></div><div class="field"><label>Pelaksana</label><input name="executor"></div><div class="field"><label>Jadwal</label><input name="schedule"></div><div class="field"><label>Progres fisik (%)</label><input name="progress" type="number" min="0" max="100"></div><div class="field"><label>Realisasi belanja (rupiah)</label><input name="spent" type="number" min="0"></div><div class="field"><label>Sumber informasi</label><input name="source"></div><div class="field wide"><label>Rincian pekerjaan</label><textarea name="details"></textarea></div><div class="field"><label>Link sumber</label><input name="sourceUrl" type="url" placeholder="https://"></div><label class="check"><input name="published" type="checkbox" checked> Tampilkan di situs</label><div class="row wide"><button class="btn" type="submit">Simpan proyek</button><button class="btn light" id="project-clear" type="button">Kosongkan form</button><span id="project-note" class="notice" role="status"></span></div></form><div id="projects" class="list"></div></section>
<section class="card admin-page" id="budget-management" data-admin-page="budgets" @if ($adminPage !== 'budgets') hidden @endif><div class="section-top"><div><h2>APBDes</h2><p class="muted">Daftar ringkasan anggaran per tahun. Data publikasi tampil di situs.</p></div><button id="budget-add" class="btn" type="button">Tambah APBDes</button></div><form hidden id="budget-form" class="grid"><input type="hidden" name="id"><div class="field"><label>Tahun anggaran</label><input name="year" type="number" min="2000" max="2100" required></div><div class="field"><label>Dana Desa (rupiah)</label><input name="villageFund" type="number" min="0"></div><div class="field"><label>Pendapatan (rupiah)</label><input name="revenue" type="number" min="0"></div><div class="field"><label>Belanja (rupiah)</label><input name="expenditure" type="number" min="0"></div><div class="field"><label>Pembiayaan (rupiah)</label><input name="financing" type="number"></div><div class="field"><label>Realisasi belanja (rupiah)</label><input name="realized" type="number" min="0"></div><div class="field"><label>Link dokumen sumber <span class="optional">(opsional)</span></label><input name="sourceUrl" type="url" placeholder="https://"></div><label class="check"><input name="published" type="checkbox" checked> Tampilkan di situs</label><div class="field wide"><label>Keterangan</label><textarea name="notes" placeholder="Catatan atau penjelasan anggaran"></textarea></div><div class="row wide"><button class="btn" type="submit">Simpan APBDes</button><button class="btn light" id="budget-clear" type="button">Kosongkan form</button><span id="budget-note" class="notice" role="status"></span></div></form><div id="budgets" class="list"></div></section>
<section class="card admin-page" id="proposal-management" data-admin-page="proposals" @if ($adminPage !== 'proposals') hidden @endif><div class="section-top"><div><h2>Usulan masuk</h2><p class="muted">Usulan dari formulir warga, termasuk status tindak lanjutnya.</p></div><span id="proposal-count" class="status">0 usulan</span></div><div id="proposals" class="table-wrap"></div></section>
@include('admin.content-manager')
</div>
</section>
</main>
<script>
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let projects=[],budgets=[],proposals=[],villageRequests=[],requestAssignees=[],canManageUsers=false,currentAdminId=0;
async function api(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json','Accept':'application/json',...(options.headers||{})}});if(!r.ok){const body=(await r.text()).trim();let message=body;try{message=JSON.parse(body).message||body}catch{}throw Error(message||'Permintaan gagal')}if(r.status===204)return null;return r.json()}
const adminSidebar=$('#admin-sidebar'),sidebarToggle=$('#sidebar-toggle'),sidebarBackdrop=$('#sidebar-backdrop'),adminNavLinks=[...document.querySelectorAll('[data-admin-link]')];
const adminPages={dashboard:{id:'dashboard-overview',title:'Dashboard',description:'Ringkasan pengelolaan website desa.'},projects:{id:'project-management',title:'Papan proyek',description:'Kelola informasi pekerjaan dan pembangunan desa.'},budgets:{id:'budget-management',title:'APBDes',description:'Kelola ringkasan anggaran desa per tahun.'},proposals:{id:'proposal-management',title:'Usulan warga',description:'Tinjau dan tindak lanjuti usulan pembangunan.'},requests:{id:'request-management',title:'Permintaan warga',description:'Kelola layanan dan pengaduan yang dikirim warga.'},content:{id:'content-management',title:'Konten website',description:'Kelola berita, layanan, serta profil dan potensi desa.'},media:{id:'media-management',title:'Media desa',description:'Kelola gambar yang digunakan pada website desa.'},analytics:{id:'analytics-management',title:'Analitik',description:'Pantau jumlah tampilan halaman website desa.'},users:{id:'user-management',title:'Akun admin',description:'Kelola akun yang memiliki akses ke dashboard desa.'}};
function setSidebarOpen(isOpen){adminSidebar.classList.toggle('is-open',isOpen);sidebarBackdrop.hidden=!isOpen;sidebarToggle.setAttribute('aria-expanded',String(isOpen));sidebarToggle.setAttribute('aria-label',isOpen?'Tutup navigasi':'Buka navigasi')}
sidebarToggle.addEventListener('click',()=>setSidebarOpen(!adminSidebar.classList.contains('is-open')));sidebarBackdrop.addEventListener('click',()=>setSidebarOpen(false));
document.addEventListener('keydown',event=>{if(event.key==='Escape')setSidebarOpen(false)});
adminNavLinks.forEach(link=>link.addEventListener('click',()=>setSidebarOpen(false)));
function showAdminPage(page){if(!adminPages[page]||(page==='users'&&!canManageUsers)){page='dashboard'}Object.entries(adminPages).forEach(([key,definition])=>{const section=$(`#${definition.id}`);if(section)section.hidden=key!==page});adminNavLinks.forEach(link=>{if(link.dataset.adminLink===page)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});$('#dashboard-page-title').textContent=adminPages[page].title;$('#dashboard-page-description').textContent=adminPages[page].description;document.title=`LinkGo | ${adminPages[page].title} · ${$('#admin-village-name').textContent}`}
function formData(form){const o=Object.fromEntries(new FormData(form));for(const k of ['id','year','progress','spent','villageFund','revenue','expenditure','financing','realized'])if(k in o)o[k]=Number(o[k]||0);o.published=form.elements.published.checked;return o}
function fill(form,item){form.reset();for(const [k,v]of Object.entries(item)){const el=form.elements[k];if(el)el.type==='checkbox'?el.checked=!!v:el.value=v??''}form.elements.id.value=item.id||''}
function clear(form){form.reset();form.elements.id.value='';const c=form.elements.published;if(c)c.checked=true}
function projectBudget(summary){const value=String(summary??'').trim().replace(/^anggaran\s+/i,'');return value||'Belum tersedia'}
function render(){ $('#project-total').textContent=projects.filter(p=>p.published).length;$('#budget-total').textContent=budgets.length;$('#proposal-total').textContent=proposals.filter(p=>p.status==='Masuk').length;renderDashboardOverview();$('#projects').innerHTML=projects.length?projects.map(p=>`<article class="item project-item"><div class="project-main"><div class="project-title-row"><h3 class="project-title">${esc(p.title)}</h3><span class="status">${esc(p.year)} · ${p.published?'Tayang':'Draft'}</span></div><p class="project-location"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg><span>${esc(p.location||'Lokasi belum diisi')}</span></p><div class="project-meta"><span>${esc(p.status||'Status belum diisi')}</span><span class="project-budget">Anggaran ${esc(projectBudget(p.summary))}</span></div></div><div class="actions project-card-actions"><button class="btn light" type="button" data-edit-project="${p.id}">Ubah</button><button class="btn delete-secondary" type="button" data-delete-project="${p.id}">Hapus</button></div></article>`).join(''):'<div class="empty">Belum ada data proyek.</div>';
 $('#budgets').innerHTML=budgets.length?budgets.map(b=>`<div class="item"><div><strong>APBDes ${b.year} <span class="status">${b.published?'Tayang':'Draft'}</span></strong><small>Pendapatan ${rupiah(b.revenue)} · Belanja ${rupiah(b.expenditure)} · Realisasi ${rupiah(b.realized)}</small></div><div class="actions"><button class="btn light" data-edit-budget="${b.id}">Ubah</button><button class="btn red" data-delete-budget="${b.id}">Hapus</button></div></div>`).join(''):'<div class="empty">Belum ada data APBDes.</div>';
 $('#proposal-count').textContent=`${proposals.length} usulan`;
 $('#proposals').innerHTML=proposals.length?`<table><thead><tr><th>Usulan</th><th>Pengusul</th><th>Dikirim</th><th>Status dan catatan</th><th>Aksi</th></tr></thead><tbody>${proposals.map(p=>`<tr><td><strong>${esc(p.title)}</strong><span class="status">${esc(p.villageSlug||'curahsawo')}</span><div>${esc(p.location)} · ${esc(p.category)}</div><p>${esc(p.description)}</p></td><td>${esc(p.name||'Anonim')}<br>${esc(p.contact||'')}</td><td>${esc(p.createdAt)}</td><td><select data-proposal-status="${p.id}"><option ${p.status==='Masuk'?'selected':''}>Masuk</option><option ${p.status==='Ditinjau'?'selected':''}>Ditinjau</option><option ${p.status==='Direncanakan'?'selected':''}>Direncanakan</option><option ${p.status==='Selesai'?'selected':''}>Selesai</option><option ${p.status==='Ditolak'?'selected':''}>Ditolak</option></select><textarea data-proposal-note="${p.id}" placeholder="Catatan admin">${esc(p.adminNote)}</textarea></td><td><button class="btn light" data-save-proposal="${p.id}">Simpan</button> <button class="btn red" data-delete-proposal="${p.id}">Hapus</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Belum ada usulan dari warga.</div>';
}
function renderDashboardOverview(){const incomingRequests=villageRequests.filter(item=>item.status==='Masuk');$('#request-total').textContent=incomingRequests.length;const overview=$('#overview-requests');if(!overview)return;overview.innerHTML=villageRequests.length?villageRequests.slice(0,4).map(item=>`<a class="overview-request" href="/admin/requests"><span><strong>${esc(item.title)}</strong><small>${esc(item.kind==='pengaduan'?'Pengaduan':'Layanan')} · ${esc(item.createdAt)}</small></span><span class="status">${esc(item.status)}</span></a>`).join(''):'<div class="empty">Belum ada permintaan warga.</div>'}
function rupiah(n){return n?new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n):'Belum tersedia'}
async function refresh(){[projects,budgets,proposals]=await Promise.all([api('/api/admin/projects'),api('/api/admin/budgets'),api('/api/admin/proposals')]);render()}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const n=$('#login-note');try{await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#username').value,password:$('#password').value})});await openDashboard()}catch(x){n.className='notice error';n.textContent=x.message}});
async function openDashboard(village=null){if(!village)village=await api('/api/admin/session');canManageUsers=village.role==='owner';currentAdminId=village.userId;$('#user-management').hidden=!canManageUsers||document.body.dataset.adminPage!=='users';$('#nav-users').hidden=!canManageUsers;$('#admin-village-name').textContent=village.name;$('#login').hidden=true;$('#dashboard').hidden=false;$('#sidebar-toggle').hidden=false;$('#logout').hidden=false;document.body.classList.remove('auth-page');document.body.classList.add('dashboard-page');const requestedPage=document.body.dataset.adminPage||'dashboard';if(requestedPage==='users'&&!canManageUsers){window.location.replace('/admin/dashboard');return}showAdminPage(requestedPage);try{await refresh()}catch(error){const notice=$('#dashboard-load-note');notice.hidden=false;notice.className='notice error';notice.textContent='Sebagian data belum berhasil dimuat. Muat ulang halaman untuk mencoba lagi.';console.error('Gagal memuat data dashboard admin:',error)}}
$('#project-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,o=formData(f),id=o.id;delete o.id;o.year=String(o.year);const n=$('#project-note');try{await api(id?`/api/admin/projects/${id}`:'/api/admin/projects',{method:id?'PUT':'POST',body:JSON.stringify(o)});clear(f);f.hidden=true;n.className='notice ok';n.textContent='Proyek tersimpan.';await refresh()}catch(x){n.className='notice error';n.textContent=x.message}});
$('#budget-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,o=formData(f),id=o.id;delete o.id;const n=$('#budget-note');try{await api(id?`/api/admin/budgets/${id}`:'/api/admin/budgets',{method:id?'PUT':'POST',body:JSON.stringify(o)});clear(f);f.hidden=true;n.className='notice ok';n.textContent='APBDes tersimpan.';await refresh()}catch(x){n.className='notice error';n.textContent=x.message}});
document.addEventListener('click',async e=>{const t=e.target;try{if(t.dataset.editProject){fill($('#project-form'),projects.find(x=>x.id==t.dataset.editProject));$('#project-form').hidden=false;scrollTo({top:300,behavior:'smooth'})}if(t.dataset.deleteProject&&confirm('Hapus data proyek ini?')){await api(`/api/admin/projects/${t.dataset.deleteProject}`,{method:'DELETE'});await refresh()}if(t.dataset.editBudget){fill($('#budget-form'),budgets.find(x=>x.id==t.dataset.editBudget));$('#budget-form').hidden=false;scrollTo({top:$('#budget-form').getBoundingClientRect().top+scrollY-80,behavior:'smooth'})}if(t.dataset.deleteBudget&&confirm('Hapus data APBDes ini?')){await api(`/api/admin/budgets/${t.dataset.deleteBudget}`,{method:'DELETE'});await refresh()}if(t.dataset.saveProposal){const id=t.dataset.saveProposal;await api(`/api/admin/proposals/${id}`,{method:'PUT',body:JSON.stringify({status:$(`[data-proposal-status="${id}"]`).value,adminNote:$(`[data-proposal-note="${id}"]`).value})});await refresh()}if(t.dataset.deleteProposal&&confirm('Hapus usulan ini?')){await api(`/api/admin/proposals/${t.dataset.deleteProposal}`,{method:'DELETE'});await refresh()}}catch(x){alert(x.message)}});
$('#project-add').addEventListener('click',()=>{clear($('#project-form'));$('#project-form').hidden=false;$('#project-form').scrollIntoView({behavior:'smooth',block:'start'})});$('#budget-add').addEventListener('click',()=>{clear($('#budget-form'));$('#budget-form').hidden=false;$('#budget-form').scrollIntoView({behavior:'smooth',block:'start'})});$('#project-clear').addEventListener('click',()=>clear($('#project-form')));$('#budget-clear').addEventListener('click',()=>clear($('#budget-form')));
$('#logout').addEventListener('click',async()=>{await fetch('/api/logout',{method:'POST'});window.location.assign('/admin')});
fetch('/api/admin/session').then(async response=>{if(!response.ok)throw Error();return openDashboard(await response.json())}).catch(()=>{$('#login').hidden=false;$('#dashboard').hidden=true;$('#sidebar-toggle').hidden=true;$('#logout').hidden=true;$('#nav-users').hidden=true;$('#admin-village-name').textContent='Administrasi desa';document.body.classList.remove('dashboard-page');document.body.classList.add('auth-page')});
const contentItems={news:[],service:[],profile:[]};
function renderContent(type){const manager=document.querySelector(`[data-content-manager="${type}"]`),list=manager.querySelector('[data-content-list]'),items=contentItems[type];manager.querySelector('[data-content-count]').textContent=items.length;manager.querySelector('[data-content-add]').hidden=type==='profile'&&items.length>0;list.hidden=items.length===0;list.innerHTML=items.map(item=>`<div class="item"><div><strong>${esc(item.title)} <span class="status">${item.published?'Tayang':'Draft'}</span></strong><small>${esc(item.summary||item.category||(item.metadata?.indexScore!==undefined?`Indeks Desa ${item.metadata.indexScore} · ${item.metadata.indexYear||'tahun belum diisi'}`:'Belum ada ringkasan'))}</small></div><div class="actions"><button class="btn light" type="button" data-content-edit="${item.id}">Ubah</button>${type==='profile'?'':`<button class="btn red" type="button" data-content-delete="${item.id}">Hapus</button>`}</div></div>`).join('');$('#content-empty-state').hidden=Object.values(contentItems).some(entries=>entries.length>0)}
async function refreshContent(){await Promise.all(Object.keys(contentItems).map(async type=>{contentItems[type]=await api(`/api/admin/content/${type}`)}));Object.keys(contentItems).forEach(renderContent)}
const originalRefresh=refresh;refresh=async function(){await Promise.all([originalRefresh(),refreshContent()])};

function renderRequests(){const target=$('#village-requests');$('#request-count').textContent=`${villageRequests.length} permintaan`;target.innerHTML=villageRequests.length?villageRequests.map(item=>`<article class="request-item"><div class="request-head"><div><strong>${esc(item.title)}</strong><span class="status">${esc(item.kind==='pengaduan'?'Pengaduan':'Layanan')} · ${esc(item.status)}</span><small>Kode ${esc(item.trackingCode)} · ${esc(item.createdAt)} · ${esc(item.category||'Umum')}</small></div><div><strong>${esc(item.name||'Warga')}</strong><small>${esc(item.contact)}</small>${item.email?'<small>'+esc(item.email)+(item.notifyByEmail?' · Notifikasi email aktif':' · Tanpa notifikasi email')+'</small>':''}</div></div><p>${esc(item.description)}</p><div class="request-controls"><label>Status<select data-request-status="${item.id}"><option ${item.status==='Masuk'?'selected':''}>Masuk</option><option ${item.status==='Ditinjau'?'selected':''}>Ditinjau</option><option ${item.status==='Diproses'?'selected':''}>Diproses</option><option ${item.status==='Selesai'?'selected':''}>Selesai</option><option ${item.status==='Ditolak'?'selected':''}>Ditolak</option></select></label><label>Penanggung jawab<select data-request-assignee="${item.id}"><option value="">Belum ditugaskan</option>${requestAssignees.map(user=>`<option value="${user.id}" ${item.assignedTo===user.id?'selected':''} ${user.active?'':'disabled'}>${esc(user.name)}${user.active?'':' (nonaktif)'}</option>`).join('')}</select></label><label>Target respons<input type="date" data-request-target="${item.id}" value="${esc(item.targetAt||'')}"></label><label class="request-note">Catatan tindak lanjut<textarea data-request-note="${item.id}" maxlength="3000">${esc(item.adminNote)}</textarea></label><button class="btn" type="button" data-save-request="${item.id}">Simpan tindak lanjut</button></div><details class="request-history"><summary>Riwayat status (${item.history.length})</summary><ol>${item.history.map(entry=>`<li>${esc(entry.status)} · ${esc(entry.updatedAt)}${entry.changedBy?` · ${esc(entry.changedBy)}`:''}</li>`).join('')}</ol></details></article>`).join(''):'<div class="empty">Belum ada permintaan warga.</div>';renderDashboardOverview()}
async function refreshRequests(){const data=await api('/api/admin/requests');villageRequests=data.items;requestAssignees=data.assignees;renderRequests()}
const refreshContentAndRequests=refresh;refresh=async function(){await Promise.all([refreshContentAndRequests(),refreshRequests()])};
let villageMedia=[];
function renderMedia(){const list=$('#village-media');list.innerHTML=villageMedia.length?villageMedia.map(item=>`<article class="item media-item"><img src="${esc(item.url)}" alt="${esc(item.altText)}" loading="lazy"><div><strong>${esc(item.originalName)}</strong><small>${esc(item.altText)} · ${(item.size/1024).toFixed(0)} KB</small></div><div class="actions"><button class="btn light" type="button" data-use-media="${item.id}">Gunakan gambar</button><button class="btn red" type="button" data-delete-media="${item.id}">Hapus</button></div></article>`).join(''):'<div class="empty">Belum ada media.</div>'}
async function refreshMedia(){villageMedia=await api('/api/admin/media');renderMedia()}
const refreshContentRequestsAndMedia=refresh;refresh=async function(){await Promise.all([refreshContentRequestsAndMedia(),refreshMedia()])};
let villageAdmins=[];
function villageAdminErrorMessage(error){const message=String(error.message||'');if(/username.*(already been taken|unique)/i.test(message))return 'Nama pengguna sudah digunakan. Pilih nama lain.';if(/email.*(already been taken|unique)/i.test(message))return 'Email sudah digunakan. Periksa kembali alamat email.';if(/password.*confirmation.*(does not match|match)/i.test(message))return 'Konfirmasi kata sandi tidak cocok.';if(/password.*(at least 12|minimum)/i.test(message))return 'Kata sandi harus terdiri dari sedikitnya 12 karakter.';if(/required/i.test(message))return 'Lengkapi semua kolom yang wajib diisi.';if(/setidaknya satu admin pemilik/i.test(message))return message;if(/^[A-Z][a-z]+ the |^The |^This /i.test(message))return 'Perubahan akun belum berhasil. Periksa kembali data lalu coba lagi.';return message||'Perubahan akun belum berhasil. Coba lagi.'}
function renderVillageAdmins(){
 const list=$('#admin-users');
 list.innerHTML=villageAdmins.length?villageAdmins.map(user=>{
  const identity=`<div class="admin-user-identity"><strong>${esc(user.name)} <span class="status">${user.active?'Aktif':'Nonaktif'}</span></strong><small>${esc(user.username)} · ${esc(user.email)}</small></div>`;
  if(user.id===currentAdminId){
   return `<article class="admin-user admin-user-self">${identity}<div class="field"><span class="field-label">Peran</span><span class="account-value">${user.role==='owner'?'Admin pemilik':'Editor'}</span></div><div class="field"><span class="field-label">Status akun</span><span class="account-value">${user.active?'Aktif':'Nonaktif'}</span></div><div class="admin-user-actions"><span class="account-self-note">Akun yang sedang digunakan</span></div></article>`;
  }
  return `<form class="admin-user" data-admin-user="${user.id}">${identity}<div class="field"><label>Peran<select name="role"><option value="owner" ${user.role==='owner'?'selected':''}>Admin pemilik</option><option value="editor" ${user.role==='editor'?'selected':''}>Editor</option></select></label></div><div class="field"><label>Status akun<select name="active"><option value="true" ${user.active?'selected':''}>Aktif</option><option value="false" ${!user.active?'selected':''}>Nonaktif</option></select></label></div><details class="admin-user-password"><summary>Ganti kata sandi</summary><div class="grid admin-user-password-fields"><div class="field"><label>Kata sandi baru<input name="password" type="password" minlength="12" autocomplete="new-password"></label></div><div class="field"><label>Konfirmasi kata sandi baru<input name="password_confirmation" type="password" minlength="12" autocomplete="new-password"></label></div></div></details><div class="admin-user-actions"><span class="notice" data-admin-user-note role="status" aria-live="polite" hidden></span><button class="btn" type="submit">Simpan perubahan</button></div></form>`;
 }).join(''):'<div class="empty account-empty">Belum ada akun admin tambahan.</div>';
}
async function refreshUsers(){if(!canManageUsers)return;villageAdmins=await api('/api/admin/users');renderVillageAdmins()}
const refreshWithUsers=refresh;refresh=async function(){await Promise.all([refreshWithUsers(),refreshUsers()])};
async function refreshAnalytics(){const data=await api('/api/admin/analytics');$('#analytics-total').textContent=new Intl.NumberFormat('id-ID').format(data.totalViews);$('#analytics-today').textContent=new Intl.NumberFormat('id-ID').format(data.todayViews);$('#analytics-period').textContent=`${data.periodStart} – ${data.periodEnd}`;$('#analytics-daily').innerHTML=data.daily.length?data.daily.map(day=>`<tr><td>${esc(day.view_date)}</td><td>${new Intl.NumberFormat('id-ID').format(day.views)}</td></tr>`).join(''):'<tr><td colspan="2">Belum ada kunjungan pada periode ini.</td></tr>'}
const refreshWithAnalytics=refresh;refresh=async function(){await Promise.all([refreshWithAnalytics(),refreshAnalytics()])};
$('#admin-user-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,notice=$('#admin-user-note'),values=Object.fromEntries(new FormData(form));try{await api('/api/admin/users',{method:'POST',body:JSON.stringify(values)});form.reset();notice.className='notice ok';notice.textContent='Akun editor berhasil dibuat. Bagikan kredensial secara aman.';await refreshUsers()}catch(error){notice.className='notice error';notice.textContent=villageAdminErrorMessage(error)}});
$('#admin-users').addEventListener('submit',async event=>{const form=event.target.closest('[data-admin-user]');if(!form)return;event.preventDefault();const values=Object.fromEntries(new FormData(form));values.active=values.active==='true';const notice=form.querySelector('[data-admin-user-note]');try{await api(`/api/admin/users/${form.dataset.adminUser}`,{method:'PUT',body:JSON.stringify(values)});await refreshUsers()}catch(error){notice.hidden=false;notice.className='notice error';notice.textContent=villageAdminErrorMessage(error)}});
$('#media-upload-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,notice=$('#media-upload-note'),button=form.querySelector('button[type="submit"]');button.disabled=true;notice.textContent='Mengunggah gambar…';const data=new FormData(form);try{const response=await fetch('/api/admin/media',{method:'POST',headers:{'Accept':'application/json'},body:data});if(!response.ok){const result=await response.json();throw Error(result.message||'Gambar belum berhasil diunggah.')}form.reset();notice.className='notice ok';notice.textContent='Gambar berhasil diunggah.';await refreshMedia()}catch(error){notice.className='notice error';notice.textContent=error.message}finally{button.disabled=false}});
$('#village-media').addEventListener('click',async event=>{const button=event.target.closest('[data-use-media],[data-delete-media]');if(!button)return;try{if(button.dataset.useMedia){const form=[...document.querySelectorAll('.content-form')].find(item=>!item.hidden),field=form?.elements.imageUrl;if(!field){alert('Buka form berita, layanan, atau profil terlebih dahulu.');return}field.value=villageMedia.find(item=>item.id===Number(button.dataset.useMedia))?.url||'';field.scrollIntoView({behavior:'smooth',block:'center'});return}if(button.dataset.deleteMedia&&confirm('Hapus media ini? Konten yang memakai URL ini akan kehilangan gambarnya.')){await api(`/api/admin/media/${button.dataset.deleteMedia}`,{method:'DELETE'});await refreshMedia()}}catch(error){alert(error.message)}});
$('#village-requests').addEventListener('click',async event=>{const button=event.target.closest('[data-save-request]');if(!button)return;const id=button.dataset.saveRequest;button.disabled=true;try{const assignee=$(`[data-request-assignee="${id}"]`).value,selectedAssignee=requestAssignees.find(user=>user.id===Number(assignee));await api(`/api/admin/requests/${id}`,{method:'PUT',body:JSON.stringify({status:$(`[data-request-status="${id}"]`).value,assignedTo:selectedAssignee?.active?Number(assignee):null,targetAt:$(`[data-request-target="${id}"]`).value||null,adminNote:$(`[data-request-note="${id}"]`).value})});await refreshRequests()}catch(error){alert(error.message)}finally{button.disabled=false}});
document.querySelectorAll('[data-content-manager]').forEach(manager=>{const type=manager.dataset.contentManager,form=manager.querySelector('.content-form'),list=manager.querySelector('[data-content-list]');manager.querySelector('[data-content-add]').addEventListener('click',()=>{clear(form);form.hidden=false;form.scrollIntoView({behavior:'smooth',block:'center'})});manager.addEventListener('click',async event=>{const button=event.target.closest('[data-content-edit],[data-content-delete],[data-content-cancel]');if(!button)return;try{if(button.hasAttribute('data-content-cancel')){clear(form);form.hidden=true;return}if(button.dataset.contentEdit){const item=contentItems[type].find(item=>item.id===Number(button.dataset.contentEdit));fill(form,item);form.querySelectorAll('[data-profile-field]').forEach(field=>{field.value=item.metadata?.[field.dataset.profileField]??''});form.hidden=false;form.scrollIntoView({behavior:'smooth',block:'center'});return}if(button.dataset.contentDelete&&confirm('Hapus konten ini?')){await api(`/api/admin/content/${type}/${button.dataset.contentDelete}`,{method:'DELETE'});await refreshContent()}}catch(error){alert(error.message)}});form.addEventListener('submit',async event=>{event.preventDefault();const values=formData(form),id=values.id;delete values.id;values.sortOrder=Number(values.sortOrder||0);values.publishedAt=values.publishedAt||null;if(type==='profile'){values.profile=Object.fromEntries([...form.querySelectorAll('[data-profile-field]')].map(field=>[field.dataset.profileField,field.value||null]))}const notice=form.querySelector('.notice');try{await api(id?`/api/admin/content/${type}/${id}`:`/api/admin/content/${type}`,{method:id?'PUT':'POST',body:JSON.stringify(values)});form.hidden=true;clear(form);notice.textContent='Konten tersimpan.';notice.className='notice ok';await refreshContent()}catch(error){notice.textContent=error.message;notice.className='notice error'}})});
</script></body></html>
